using System;using System.Collections.Generic;using System.Globalization;using System.Linq;using System.Text;using System.Windows.Forms;
namespace BeamScheduleFormatter {
partial class ProgramOfWorksForm {
 DataGridView steelPurlins,steelAngles,machineBolts,anchorBolts,steelPlates,crossBracing,fasciaFrame,steelCutGrid;
 readonly List<SteelCutDemand> steelDemands=new List<SteelCutDemand>();List<SteelStock> steelStocks=new List<SteelStock>();List<PlateSheet> plateStocks=new List<PlateSheet>();
 static readonly string[] SteelSections={"SteelPurlins","SteelAngles","MachineBolts","AnchorBolts","SteelPlates","CrossBracing","FasciaFrame"};
 static readonly string[] SteelPageNames={"Purlin Estimate","Angle Bars","Machine Bolts","Anchor Bolts","Steel Plates","Crossbracing","Metal Fascia Frame"};
 void AddStructuralSteel(){
  steelPurlins=SteelMemberGrid("Purlin");steelAngles=SteelMemberGrid("Angle bar");AddGrid(SteelPageNames[0],steelPurlins,"Select a handbook profile, enter cut length and quantity. Stock is fixed at 6m. Matching profile/specification offcuts are shared across compatible members automatically. Cuts over 6m require an approved splice detail.");AddGrid(SteelPageNames[1],steelAngles,"Angle-bar stock is fixed at 6m. Cutting plan reuses remaining lengths across compatible angle and fascia entries. Specify the same grade/finish only when the stock is interchangeable.");
  machineBolts=SteelBoltGrid();anchorBolts=SteelBoltGrid();AddGrid(SteelPageNames[2],machineBolts,"A307 or A325. Overall developed length in mm. Weight = pi x diameter^2 / 4 x overall length x 7850 kg/m3 x quantity. Shaft-only estimate: heads, nuts and washers are excluded. Grade selection identifies material; this is not a connection design check.");AddGrid(SteelPageNames[3],anchorBolts,"A307 or A325. Overall developed length must include all straight and bent/hooked portions. Shaft weight only, excluding heads, nuts and washers. Anchorage/embedment strength is not inferred.");
  steelPlates=Grid(new[]{"ID","Description","Area m2 / pc (OR dimensions)","Length m","Width m","Thickness (mm)","Qty","Total area m2","Net weight kg","Sheets used (may be shared)","Selected stock sheets","Purchase weight kg","Allocated offcut kg","Status"},7);SetDefaults(steelPlates,new Dictionary<int,string>{{5,"6"},{6,"1"}});AddGrid(SteelPageNames[4],steelPlates,"Enter area per plate OR length and width, then thickness in mm and quantity (enter 6 for a 6 mm plate). Weight (kg) = area (m2) x thickness (mm) / 1000 x 7850 (kg/m3) x quantity. For sheet purchasing, enter length and width. Matching-thickness cuts share offcuts; handbook stock sizes are compared with 90-degree rotation. Lowest purchase weight among compared feasible layouts is selected; zero kerf. Area-only entries calculate net weight but need dimensions before purchase quantities can be finalized.");
  crossBracing=Grid(new[]{"ID","Description","X distance m","Y offset m","Height m","Rod dia mm","Bracing lines","Diagonal m / line","Total rod length m","Rod weight kg","Turnbuckles pcs","Turnbuckle size mm","Status"},7);SetDefaults(crossBracing,new Dictionary<int,string>{{3,"0"},{5,"12"},{6,"1"}});AddGrid(SteelPageNames[5],crossBracing,"Diagonal = sqrt(X^2 + Y^2 + height^2). Use Y=0 for planar bracing. Each line has one turnbuckle of the same nominal diameter. An X pair is TWO lines. Rod weight excludes turnbuckles and connection hardware; no turnbuckle length is deducted.");
  fasciaFrame=Grid(new[]{"ID","Description","Member type","Handbook section","Material grade / finish","Cut length m","Qty","Flat width mm","Flat thickness mm","Unit mass kg/m","Net weight kg","Status"},9);AddCombo(fasciaFrame,2,"Member type",new[]{"Angle bar","Flat bar"});AddCombo(fasciaFrame,3,"Handbook section",SteelCatalog.Profiles.Where(p=>p.Kind=="Angle bar"||p.Kind=="Flat bar").Select(p=>p.Name).ToArray());SetDefaults(fasciaFrame,new Dictionary<int,string>{{2,"Angle bar"},{3,SteelCatalog.Profiles.First(p=>p.Kind=="Angle bar").Name},{4,"Project specification"},{6,"1"}});AddGrid(SteelPageNames[6],fasciaFrame,"Angle and flat bars use fixed 6m stock. Select the member type first; only its handbook sections are offered. Flat-bar width and thickness are read from the section. Compatible offcuts can serve other fascia rows and matching angle-bar entries.");
  fasciaFrame.Columns[7].ReadOnly=fasciaFrame.Columns[8].ReadOnly=true;
  steelCutGrid=Grid(new[]{"Stock no.","Profile / specification","Cut order","Member ID","Cut m","Remaining after cut m","Next use","Final leftover m"},0);steelCutGrid.ReadOnly=true;steelCutGrid.AllowUserToAddRows=false;steelCutGrid.Columns[1].Width=350;
  foreach(var grid in new[]{steelPurlins,steelAngles,machineBolts,anchorBolts,fasciaFrame}){grid.CurrentCellDirtyStateChanged+=(s,e)=>{if(grid.IsCurrentCellDirty&&grid.CurrentCell is DataGridViewComboBoxCell)grid.CommitEdit(DataGridViewDataErrorContexts.Commit);};grid.CellValueChanged+=(s,e)=>{if(!filling&&e.RowIndex>=0&&(e.ColumnIndex==2||e.ColumnIndex==3))Recalculate();};}
 }
 DataGridView SteelMemberGrid(string kind){var grid=Grid(new[]{"ID","Description","Handbook profile","Material grade / finish","Cut length m","Qty","Unit mass kg/m","Net weight kg","Status"},6);AddCombo(grid,2,"Handbook profile",SteelCatalog.Profiles.Where(p=>p.Kind==kind).Select(p=>p.Name).ToArray());grid.Columns[2].Width=260;SetDefaults(grid,new Dictionary<int,string>{{3,"Project specification"},{5,"1"}});return grid;}
 DataGridView SteelBoltGrid(){var grid=Grid(new[]{"ID","Description","Grade","Diameter mm","Overall developed length mm","Qty","Total length m","Shaft weight kg","Status"},6);AddCombo(grid,2,"Grade",new[]{"A307","A325"});SetDefaults(grid,new Dictionary<int,string>{{2,"A307"},{3,"16"},{5,"1"}});return grid;}
 Dictionary<string,DataGridView> SteelTables(){if(steelPurlins==null)return new Dictionary<string,DataGridView>();return new Dictionary<string,DataGridView>{{SteelSections[0],steelPurlins},{SteelSections[1],steelAngles},{SteelSections[2],machineBolts},{SteelSections[3],anchorBolts},{SteelSections[4],steelPlates},{SteelSections[5],crossBracing},{SteelSections[6],fasciaFrame}};}
 static int SteelInputCount(string section){return section=="SteelPlates"||section=="CrossBracing"?7:section=="FasciaFrame"?9:6;}
 void RecalculateStructuralSteel(){if(steelPurlins==null)return;steelDemands.Clear();steelStocks.Clear();plateStocks.Clear();var ids=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
  foreach(var pair in SteelTables()){var grid=pair.Value;int first=SteelInputCount(pair.Key),last=grid.Columns.Count-1;foreach(DataGridViewRow row in grid.Rows){if(grid==fasciaFrame)FilterFasciaSections(row);if(row.IsNewRow)continue;row.Tag=null;for(int c=first;c<=last;c++)row.Cells[c].Value="";if(Empty(row))continue;try{if(Cell(row,0)==""||Cell(row,1)=="")throw new Exception("Enter ID and description.");if(!ids.Add(Cell(row,0)))throw new Exception("Steel IDs must be unique across tabs.");if(grid==steelPurlins||grid==steelAngles){var profile=FindSteelProfile(Cell(row,2));if(profile==null||profile.Kind!=(grid==steelPurlins?"Purlin":"Angle bar"))throw new Exception("Select a matching handbook profile.");var demand=AddSteelDemand(row,profile.Name,Cell(row,3),Number(row,4),Count(row,5),profile.KgM);row.Cells[6].Value=profile.KgM;Measure(row,7,demand.Length*demand.Quantity*profile.KgM);}
    else if(grid==machineBolts||grid==anchorBolts){if(!new[]{"A307","A325"}.Contains(Cell(row,2)))throw new Exception("Select A307 or A325.");double length=Number(row,4)/1000;int qty=Count(row,5);Measure(row,6,length*qty,"0.000");Measure(row,7,SteelWeight.Rod(Number(row,3),length,qty));}
    else if(grid==steelPlates){bool area=Cell(row,2)!="";if(area&&(Cell(row,3)!=""||Cell(row,4)!=""))throw new Exception("Use area OR length and width, not both.");double squareMetres;if(area)squareMetres=Number(row,2);else{double length=Number(row,3),width=Number(row,4);SteelWeight.Positive(length,width);squareMetres=length*width;}int qty=Count(row,6);Measure(row,7,squareMetres*qty,"0.000");double thickness=Number(row,5);Measure(row,8,SteelWeight.Plate(squareMetres,thickness,qty));if(!area)row.Tag=new PlateDemand{Member=Cell(row,0),Length=Number(row,3),Width=Number(row,4),ThicknessMm=thickness,Quantity=qty};else{row.Cells[10].Value="Enter dimensions for sheet purchase";errors.Add("Steel "+Cell(row,0)+": net plate weight calculated; length and width required to verify whole-sheet purchase.");}}
    else if(grid==crossBracing){double diagonal=SteelWeight.Diagonal(Number(row,2),Cell(row,3)==""?0:Number(row,3),Number(row,4)),diameter=Number(row,5);int lines=Count(row,6);Measure(row,7,diagonal,"0.000");Measure(row,8,diagonal*lines,"0.000");Measure(row,9,SteelWeight.Rod(diameter,diagonal,lines));row.Cells[10].Value=lines;row.Cells[11].Value=diameter;}
    else{bool flat=Cell(row,2)=="Flat bar";if(!flat&&Cell(row,2)!="Angle bar")throw new Exception("Select angle or flat bar.");row.Cells[3].ReadOnly=false;row.Cells[7].ReadOnly=row.Cells[8].ReadOnly=true;var selected=FindSteelProfile(Cell(row,3));if(selected==null||selected.Kind!=(flat?"Flat bar":"Angle bar"))throw new Exception("Choose a matching handbook section.");string profile=selected.Name;double mass=selected.KgM;if(flat){Measure(row,7,selected.B,"0.###");Measure(row,8,selected.T,"0.###");}else{row.Cells[7].Value=row.Cells[8].Value="";}var demand=AddSteelDemand(row,profile,Cell(row,4),Number(row,5),Count(row,6),mass);Measure(row,9,mass,"0.000");Measure(row,10,mass*demand.Length*demand.Quantity);}row.Cells[last].Value="Estimated";
   }catch(Exception ex){row.Cells[last].Value=ex.Message;errors.Add("Steel "+Cell(row,0)+": "+ex.Message);}}}
  CalculatePlatePurchases();
  try{steelStocks=SteelCutPlanner.Allocate(steelDemands);}catch(Exception ex){errors.Add("Steel cutting: "+ex.Message);}steelCutGrid.Rows.Clear();foreach(var stock in steelStocks)for(int i=0;i<stock.Cuts.Count;i++){var cut=stock.Cuts[i];steelCutGrid.Rows.Add(stock.Number,stock.Specification,i+1,cut.Demand.Member,cut.Demand.Length,cut.RemainingAfter,i+1<stock.Cuts.Count?"Reused for "+stock.Cuts[i+1].Demand.Member:"Leftover / stockpile",i+1==stock.Cuts.Count?(object)stock.Remaining:"");}
 }
 static void Measure(DataGridViewRow row,int column,double value,string format="0.00"){row.Cells[column].Value=value;row.Cells[column].Style.Format=format;}
 double SteelTotal(DataGridView grid,int column){return grid.Rows.Cast<DataGridViewRow>().Where(row=>!row.IsNewRow&&Cell(row,grid.Columns.Count-1)=="Estimated").Sum(row=>Convert.ToDouble(row.Cells[column].Value,CultureInfo.InvariantCulture));}
 List<object[]> SteelSummary(){double net=SteelTotal(steelPurlins,7)+SteelTotal(steelAngles,7)+SteelTotal(fasciaFrame,10),other=SteelTotal(machineBolts,7)+SteelTotal(anchorBolts,7)+SteelTotal(steelPlates,8)+SteelTotal(crossBracing,9);var rows=new List<object[]>{new object[]{"Purlins net steel",SteelTotal(steelPurlins,7),"kg"},new object[]{"Angle bars net steel",SteelTotal(steelAngles,7),"kg"},new object[]{"Metal fascia net steel",SteelTotal(fasciaFrame,10),"kg"},new object[]{"6m stock bars to buy (purlin/angle/fascia)",steelStocks.Count,"pcs"},new object[]{"6m stock PURCHASE weight",steelStocks.Sum(stock=>6*stock.KgM),"kg"},new object[]{"Final stock leftovers",steelStocks.Sum(stock=>stock.Remaining),"m"},new object[]{"Final stock leftover weight",steelStocks.Sum(stock=>stock.Remaining*stock.KgM),"kg"},new object[]{"Machine bolts shaft-only",SteelTotal(machineBolts,7),"kg"},new object[]{"Anchor bolts shaft-only",SteelTotal(anchorBolts,7),"kg"},new object[]{"Steel plates",SteelTotal(steelPlates,8),"kg"},new object[]{"Steel plates PURCHASE weight",plateStocks.Sum(p=>p.BuyKg),"kg"},new object[]{"Steel plates final offcuts",plateStocks.Sum(p=>p.WasteKg),"kg"},new object[]{"Crossbracing rods",SteelTotal(crossBracing,9),"kg"},new object[]{"TOTAL installed steel (listed items)",net+other,"kg"},new object[]{"TOTAL purchase steel (stock + nonstock items)",steelStocks.Sum(stock=>6*stock.KgM)+other-SteelTotal(steelPlates,8)+plateStocks.Sum(p=>p.BuyKg),"kg"}};foreach(var group in crossBracing.Rows.Cast<DataGridViewRow>().Where(row=>!row.IsNewRow&&Cell(row,12)=="Estimated").GroupBy(row=>Number(row,5)))rows.Add(new object[]{"Turnbuckles dia "+group.Key.ToString("0.###",CultureInfo.InvariantCulture)+"mm",group.Sum(row=>Count(row,6)),"pcs"});return rows;}
 SteelCutDemand AddSteelDemand(DataGridViewRow row,string profile,string spec,double length,int qty,double mass){if(string.IsNullOrWhiteSpace(spec))throw new Exception("Enter material grade/finish to identify interchangeable stock.");SteelWeight.Positive(length,mass);SteelWeight.Count(qty);if(length>6+1e-9)throw new Exception("Cut length exceeds 6m; enter an approved segmented detail separately.");var demand=new SteelCutDemand{Member=Cell(row,0),Specification=profile+" | "+spec.Trim(),Length=length,Quantity=qty,KgM=mass};steelDemands.Add(demand);row.Tag=demand;return demand;}
 void AppendStructuralSteelReport(StringBuilder b,bool detailed){b.AppendLine();b.AppendLine("STRUCTURAL STEEL | QUANTITIES & PURCHASE SUMMARY");foreach(var total in SteelSummary())b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0}: {1:0.###} {2}",total[0],total[1],total[2]));foreach(var group in steelStocks.GroupBy(s=>s.Specification)){b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0}: {1} stock pcs x 6m | net {2:0.000}m / {3:0.00}kg | buy {4:0.00}kg | leftover {5:0.000}m / {6:0.00}kg",group.Key,group.Count(),group.Sum(s=>s.Net),group.Sum(s=>s.Net*s.KgM),group.Sum(s=>6*s.KgM),group.Sum(s=>s.Remaining),group.Sum(s=>s.Remaining*s.KgM)));}foreach(var pair in SteelTables()){if(pair.Key=="SteelPurlins"||pair.Key=="SteelAngles"||pair.Key=="FasciaFrame")continue;var grid=pair.Value;b.AppendLine(pair.Key);foreach(DataGridViewRow row in grid.Rows)if(!row.IsNewRow&&!Empty(row)&&Cell(row,grid.Columns.Count-1)=="Estimated"){b.AppendLine("  "+Cell(row,0)+" | "+Cell(row,1)+" | "+(grid==crossBracing?"rod "+Cell(row,9)+" kg; "+Cell(row,10)+" turnbuckles at dia "+Cell(row,11)+"mm; diagonal "+Cell(row,7)+"m":grid==steelPlates?Cell(row,8)+" kg; area "+Cell(row,7)+"m2; thickness "+Cell(row,5)+" mm; purchase "+Cell(row,11)+" kg; sheets "+Cell(row,10):Cell(row,2)+" dia "+Cell(row,3)+"mm; total length "+Cell(row,6)+"m; shaft "+Cell(row,7)+"kg"));}}
  b.AppendLine("Plates: "+PlateCatalog.Source+". Thickness input is mm. Purchase masses use nominal sheet dimensions and 7850kg/m3; rounded handbook masses may differ slightly. Cuts rotate 90 degrees; compatible offcuts are reused within each thickness. Lowest kg among compared feasible guillotine layouts, zero kerf; no global optimum guarantee.");foreach(var group in plateStocks.GroupBy(p=>new{p.ThicknessMm,p.Format.Name}))b.AppendLine(group.Key.ThicknessMm.ToString("0.###",CultureInfo.InvariantCulture)+" mm | "+group.Key.Name+" | "+group.Count()+" whole sheets | buy "+group.Sum(p=>p.BuyKg).ToString("0.00",CultureInfo.InvariantCulture)+" kg | offcut "+group.Sum(p=>p.WasteKg).ToString("0.00",CultureInfo.InvariantCulture)+" kg");
  b.AppendLine("Density 7850kg/m3. Purlin/angle kg/m from the stated handbook profile; flat bars/plates/rods from dimensions. Hardware weights exclude bolt heads, nuts, washers and turnbuckles. Crossbracing: one same-diameter turnbuckle per line.");b.AppendLine("6m stock: best-fit decreasing, shared compatible offcuts, zero cutting kerf. Final leftover counted once per stock; not an optimality guarantee.");}
 void StructuralSteelExcel(List<WorksExcelTable> tables){tables.Add(new WorksExcelTable("POW Structural Steel Summary",new[]{"Item","Quantity","Unit"},SteelSummary()));foreach(var pair in SteelTables()){var grid=pair.Value;var rows=grid.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow&&!Empty(r)).Select(r=>Enumerable.Range(0,grid.Columns.Count).Select(c=>r.Cells[c].Value??"").ToArray()).ToList();tables.Add(new WorksExcelTable("POW "+pair.Key,grid.Columns.Cast<DataGridViewColumn>().Select(c=>c.HeaderText).ToArray(),rows));}}
}
}
